CREATE TABLE accounts(id VARCHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(100), super_admin BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE tenants(id VARCHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, address VARCHAR(500), structure VARCHAR(50), plan VARCHAR(50) NOT NULL DEFAULT 'PENDING', status VARCHAR(30) NOT NULL DEFAULT 'TRIAL', incoming_days INT NOT NULL DEFAULT 7, outgoing_days INT NOT NULL DEFAULT 7);
CREATE TABLE units(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), block_name VARCHAR(60) NOT NULL, number VARCHAR(60) NOT NULL, UNIQUE(tenant_id,block_name,number));
CREATE TABLE memberships(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), account_id VARCHAR(36) NOT NULL REFERENCES accounts(id), role VARCHAR(20) NOT NULL, unit_id VARCHAR(36) REFERENCES units(id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX memberships_lookup ON memberships(tenant_id,account_id,active);
CREATE TABLE sessions(token_hash VARCHAR(64) PRIMARY KEY, account_id VARCHAR(36) NOT NULL REFERENCES accounts(id), expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE access_tokens(token_hash VARCHAR(64) PRIMARY KEY, account_id VARCHAR(36) NOT NULL REFERENCES accounts(id), kind VARCHAR(20) NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE locations(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,name));
CREATE TABLE parcels(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), unit_id VARCHAR(36) NOT NULL REFERENCES units(id), recipient_id VARCHAR(36) NOT NULL REFERENCES accounts(id), kind VARCHAR(20) NOT NULL, description VARCHAR(500) NOT NULL, volumes INT NOT NULL CHECK(volumes>0), location_id VARCHAR(36) REFERENCES locations(id), carrier VARCHAR(160), authorized VARCHAR(200), instructions VARCHAR(1000), expected_date VARCHAR(10), status VARCHAR(30) NOT NULL, created_by VARCHAR(36) NOT NULL REFERENCES accounts(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, received_by VARCHAR(36) REFERENCES accounts(id), received_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, completed_by VARCHAR(36) REFERENCES accounts(id), collected_by VARCHAR(160), method VARCHAR(30), hold_photo BOOLEAN NOT NULL DEFAULT FALSE, photo_removed_at TIMESTAMP WITH TIME ZONE, version INT NOT NULL DEFAULT 0);
CREATE INDEX parcels_tenant_status ON parcels(tenant_id,status,created_at);
CREATE TABLE media(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), parcel_id VARCHAR(36) NOT NULL REFERENCES parcels(id), kind VARCHAR(20) NOT NULL, bytes_base64 TEXT NOT NULL, mime VARCHAR(50) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL REFERENCES tenants(id), parcel_id VARCHAR(36), actor_id VARCHAR(36) REFERENCES accounts(id), event VARCHAR(80) NOT NULL, detail VARCHAR(2000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX audit_lookup ON audit(tenant_id,parcel_id,created_at);
CREATE TABLE outbox(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) REFERENCES tenants(id), parcel_id VARCHAR(36), actor_id VARCHAR(36), destination VARCHAR(254) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, next_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE failures(id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36), actor_id VARCHAR(36), request_id VARCHAR(36) NOT NULL, feature VARCHAR(100) NOT NULL, operation VARCHAR(100) NOT NULL, exception_type VARCHAR(160), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
